(D/'index.html').write_text('<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Chaspiral · linha</title><style>body{max-width:1200px;margin:auto;padding:24px;background:#f7f2e7;color:#243d42;font:18px/1.6 system-ui}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}article{background:white;padding:24px}img{width:100%;height:430px;object-fit:contain}a:focus-visible{outline:3px solid #b74658}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style><h1>Chaspiral · da surpresa à cadência imperial</h1><p>Bebê e jovem em avaliação; nomes e requisitos novos propostos. Aprovação visual não equivale a integração.</p><a href="CHART.md">Decisões</a> · <a href="chart.json">Chart</a><main class="grid">'+cards+'</main></html>',encoding='utf-8')
assert all((D/n['art']).is_file() for n in nodes)
